-- 0062_tallaby_classic_template_v2.sql (PLAN.md P4-03)
--
-- Tallaby Classic v2: the full classic template from
-- packages/store-sections/src/templates/tallaby-classic.ts (generated by
-- `pnpm --filter @workspace/store-sections classic:sql`; a test checks this
-- file matches). Replaces the v1 placeholder from 0052 as the current version.
--
-- Idempotent.

INSERT INTO template_versions (template_id, version, schema_version, config, changelog)
SELECT t.id, 2, 1,
-- classic-config:start
'{"schemaVersion":1,"designSystem":{"colors":{},"typography":{},"spacing":{}},"header":{"id":"classic-header","sectionId":"classic-header","version":1,"props":{}},"footer":{"id":"classic-footer","sectionId":"classic-footer","version":1,"props":{}},"settings":{"defaultLocale":"ar","locales":["ar","en"]},"pages":[{"slug":"home","isHome":true,"name":"الرئيسية","seo":{},"content":{"sections":[{"id":"classic-hero","sectionId":"classic-hero","version":1,"props":{}},{"id":"classic-categories","sectionId":"classic-categories","version":1,"props":{"title":""}},{"id":"classic-catalog","sectionId":"classic-catalog","version":1,"props":{}}]}}]}'::jsonb,
-- classic-config:end
  'Full Tallaby Classic: classic header, store front, category circles, all products, classic footer'
FROM templates t
WHERE t.key = 'tallaby-classic'
ON CONFLICT (template_id, version) DO NOTHING;

UPDATE templates t SET current_version_id = v.id, updated_at = now()
FROM template_versions v
WHERE t.key = 'tallaby-classic' AND v.template_id = t.id AND v.version = 2
  AND t.current_version_id IS DISTINCT FROM v.id;

-- Rollback: point templates.current_version_id back to version 1 and delete version 2.
